select test_assert((select count(*)=1 from orders),'10 concurrent requests create exactly one order');
select test_assert((select count(*)=1 from order_items),'one immutable item');
select test_assert((select count(*)=1 from order_events),'one initial event');
select test_assert((select count(*)=1 from idempotency_records),'one idempotency record');
select test_assert((select total_minor=2500 and status='pending_acceptance' and acceptance_mode='manual' from orders),'server total and manual default');
select test_assert(guest_order(repeat('d',64),(select id from orders limit 1)) is null,'same table other guest cannot read order');
select test_assert(guest_order(repeat('e',64),(select id from orders limit 1)) is null,'other tenant cannot read order');
insert into dining_tables(tenant_id,id,name) values('40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003','Other table');
insert into table_qr_tokens(tenant_id,table_id,token_hash,version) values('40000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003',repeat('1',64),1);
select open_guest_session(repeat('1',64),repeat('f',64));
select test_error($q$select create_guest_order(repeat('f',64),'wrong-context',test_payload())$q$,'SESSION_REQUIRED');
select test_assert(guest_order(repeat('f',64),(select id from orders limit 1)) is null,'same tenant other table cannot read order');
select test_error($q$select create_guest_order(repeat('c',64),'parallel',test_payload(quantity=>3))$q$,'IDEMPOTENCY_CONFLICT');
update products set name='New coffee',price_minor=1500 where tenant_id='40000000-0000-0000-0000-000000000001';
select test_assert((select product_name='Coffee' and unit_price_minor=1250 from order_items),'snapshots survive menu edit');
select test_error($q$update order_items set unit_price_minor=1$q$,'ORDER_ITEMS_IMMUTABLE');
select test_error($q$select create_guest_order(repeat('c',64),'stale',test_payload() || '{"version":0}')$q$,'MENU_CHANGED');
update tenant_settings set acceptance_mode='automatic' where tenant_id='40000000-0000-0000-0000-000000000001';
select create_guest_order(repeat('c',64),'auto',test_payload());
select test_assert((select count(*)=1 from orders where status='accepted' and acceptance_mode='automatic'),'automatic initial acceptance');
select test_assert((select count(*)=1 from orders where status='pending_acceptance'),'old order remains pending');
-- Force an item insertion error after the order header is inserted.
create function public.test_fail_item() returns trigger language plpgsql as $$ begin raise exception 'FORCED_ITEM_FAILURE'; end $$;
create trigger test_fail_item before insert on order_items for each row execute function public.test_fail_item();
select test_error($q$select create_guest_order(repeat('c',64),'rollback',test_payload())$q$,'FORCED_ITEM_FAILURE');
select test_assert((select count(*)=2 from orders) and (select count(*)=2 from order_events) and (select count(*)=2 from idempotency_records),'item failure rolls back header event and key');
drop trigger test_fail_item on order_items;
update products set available=false where tenant_id='40000000-0000-0000-0000-000000000001';
select test_error($q$select create_guest_order(repeat('c',64),'unavailable',test_payload())$q$,'PRODUCT_UNAVAILABLE');
update products set available=true where tenant_id='40000000-0000-0000-0000-000000000001';
update products set archived_at=now() where tenant_id='40000000-0000-0000-0000-000000000001';
select test_error($q$select create_guest_order(repeat('c',64),'archived',test_payload())$q$,'PRODUCT_UNAVAILABLE');
update products set archived_at=null where tenant_id='40000000-0000-0000-0000-000000000001';
update categories set archived_at=now() where tenant_id='40000000-0000-0000-0000-000000000001';
select test_error($q$select create_guest_order(repeat('c',64),'category',test_payload())$q$,'PRODUCT_UNAVAILABLE');
update categories set archived_at=null where tenant_id='40000000-0000-0000-0000-000000000001';
update products set price_minor=2147483647 where tenant_id='40000000-0000-0000-0000-000000000001';
select test_error($q$select create_guest_order(repeat('c',64),'overflow',test_payload())$q$,'INVALID_INPUT');
update products set price_minor=1500 where tenant_id='40000000-0000-0000-0000-000000000001';
select create_guest_order(repeat('c',64),'third',test_payload());
select test_error($q$select create_guest_order(repeat('c',64),'fourth',test_payload())$q$,'RATE_LIMIT');
select test_assert((select count(*)=3 from orders),'rate limit does not write a fourth order');
update tenant_settings set ordering_enabled=false;
select test_error($q$select create_guest_order(repeat('c',64),'closed',test_payload())$q$,'ORDERING_CLOSED');
select test_assert(guest_order(repeat('c',64),(select id from orders limit 1)) is not null,'existing tracking survives ordering closure');
update dining_tables set active=false;
select test_assert(guest_order(repeat('c',64),(select id from orders limit 1)) is not null,'tracking survives inactive table');
update guest_sessions set revoked_at=now() where session_hash=repeat('c',64);
select test_error($q$select create_guest_order(repeat('c',64),'revoked',test_payload())$q$,'SESSION_REQUIRED');
select test_assert(guest_order(repeat('c',64),(select id from orders limit 1)) is null,'revoked guest cannot track');
update guest_sessions set expires_at=now()-interval '1 second',created_at=now()-interval '1 hour' where session_hash=repeat('d',64);
select test_error($q$select create_guest_order(repeat('d',64),'expired',test_payload())$q$,'SESSION_REQUIRED');
